insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('riskchange', 'intermediate', 'module', 'm01-a-change-and-its-stages', 1, 'Straight from "Review" to the Closed stage: which sentence does the stage machine return?', '["It allows the move, because the Closed stage is in effect and Review is an active stage.", "It refuses: A closed change is final.", "It refuses: A change in Review can only move to Approval, Rejected, Cancelled, Screening.", "It allows the move once every approval level has signed and nothing on the set is rejected."]'::jsonb, 2, 'The row for "Review" lists four legal next stages and the Closed stage is not one of them. No row skips a stage, and the refusal quotes the row it was read from.'),
  ('riskchange', 'intermediate', 'module', 'm01-a-change-and-its-stages', 2, 'Which stage is the only one the stage machine lets into "Implementation"?', '["\"Approval\".", "\"Review\", once the reviewers named on the change have finished with it.", "Any active stage whose approval set reads complete on the day it is asked.", "\"Screening\", on the emergency route that an Emergency change is allowed."]'::jsonb, 0, 'Only "Approval" leads to "Implementation". The emergency route changes how many levels must sign at that one door; it opens no second door.'),
  ('riskchange', 'intermediate', 'module', 'm01-a-change-and-its-stages', 3, 'How many stages lead nowhere, and which are they?', '["2: \"Rejected\" and \"Cancelled\", since a Closed change can go back to Review.", "3: \"Closed\", \"Rejected\" and \"Cancelled\", whose rows read none.", "3: \"Implementation\", \"Closed\" and \"Rejected\".", "4: \"Closed\", \"Rejected\", \"Cancelled\" and \"Draft\", which cannot be rejected."]'::jsonb, 1, 'The engine prints it: 3 stages lead nowhere. These are the terminal stages, and moving any of them is refused with a sentence such as "A closed change is final."'),
  ('riskchange', 'intermediate', 'module', 'm01-a-change-and-its-stages', 4, 'Can a change in "Draft" be moved to "Rejected"?', '["Yes. \"Rejected\" can be reached from every active stage.", "Yes, once an approver has recorded a Rejected row on it.", "No, because \"Rejected\" is reachable from \"Approval\" alone.", "No. The \"Draft\" row offers only \"Screening\" and \"Cancelled\", so a draft is withdrawn by cancelling it."]'::jsonb, 3, '"Rejected" appears in three rows: "Screening", "Review" and "Approval". The "Draft" row lists two moves and neither is "Rejected".'),
  ('riskchange', 'intermediate', 'module', 'm01-a-change-and-its-stages', 5, 'From which stages can a change step back to the stage before?', '["\"Review\", \"Approval\" and \"Implementation\", each back one step for rework.", "Every active stage, with the single exception of \"Draft\", which has none before it.", "\"Screening\", \"Review\" and \"Approval\".", "Only \"Approval\", which can hand a change back to \"Review\" for more work."]'::jsonb, 2, 'Screening returns a change to "Draft", Review to "Screening" and Approval to "Review". "Implementation" has no step back: its row offers "Closed" and "Cancelled" and nothing else.'),
  ('riskchange', 'intermediate', 'module', 'm01-a-change-and-its-stages', 6, 'A change in "Implementation" is asked to go back to "Approval". Which sentence does the engine return?', '["A change in Implementation can only move to Closed, Cancelled, Approval.", "A change in Implementation can only move to Closed, Cancelled.", "Approval levels 2 and 3 have not signed yet.", "A change in Implementation is on the facility and cannot be moved back to any earlier stage."]'::jsonb, 1, 'The refusal lists the row for "Implementation", which holds two moves. The engine''s sentence names the stage and the legal moves; it does not describe the facility.'),
  ('riskchange', 'intermediate', 'module', 'm01-a-change-and-its-stages', 7, 'Which stages make up the in-effect list, the change on the facility?', '["\"Implementation\" alone.", "\"Approval\", \"Implementation\" and \"Closed\", from the signature onward.", "\"Closed\", \"Rejected\" and \"Cancelled\", the stages whose rows read none.", "\"Implementation\" and \"Closed\"."]'::jsonb, 3, 'In effect is "Implementation" and "Closed". The terminal list, "Closed", "Rejected" and "Cancelled", overlaps it only at the Closed stage.'),
  ('riskchange', 'intermediate', 'module', 'm01-a-change-and-its-stages', 8, '"Implementation" is an active stage. Which other list does it also sit in, and what follows from that?', '["In effect: it can expire, and cannot read overdue.", "Terminal: its actions leave the open count once it is reached.", "No other list; each stage sits in exactly one of the three.", "In effect: its actions leave the open count once the target passes."]'::jsonb, 0, 'Two stages sit in two lists: "Implementation" is active and in effect, and the Closed stage is in effect and terminal. Being on the facility is what lets a change expire and what ends its overdue flag.'),
  ('riskchange', 'intermediate', 'module', 'm01-a-change-and-its-stages', 9, 'The ESANMI register holds 5 changes in "Implementation" on 2026-10-01, and all 5 are past their target dates. How many read overdue on that date?', '["All 5, because each change''s target implementation date has passed by 2026-10-01.", "None of them. A change is overdue only before it is on the facility, and late work there shows as overdue actions.", "Only those whose actions are still open on 2026-10-01.", "Only the Emergency ones, whose ratification is also running late on that date."]'::jsonb, 1, 'The overdue flag on a change is read in "Draft", "Screening", "Review" and "Approval" only. Being in effect means the target was met or passed by the fact of it, so none of the 5 reads overdue on 2026-10-01.'),
  ('riskchange', 'intermediate', 'module', 'm01-a-change-and-its-stages', 10, 'The ESANMI summary reads active 8 on 2026-10-01. Which stage counts add up to it?', '["\"Implementation\" 5 and \"Closed\" 2, which are in effect, plus the 1 \"Rejected\" change.", "\"Implementation\" 5 plus ES-06, ES-09 and ES-11.", "\"Implementation\" 5 plus the 3 Emergency changes.", "\"Draft\" 0, \"Screening\" 1, \"Review\" 1, \"Approval\" 1 and \"Implementation\" 5."]'::jsonb, 3, 'Active is "Draft", "Screening", "Review", "Approval" and "Implementation": 0 + 1 + 1 + 1 + 5 = 8. Every distractor here also adds to 8, which is why the list behind a count matters more than the count.'),
  ('riskchange', 'intermediate', 'module', 'm01-a-change-and-its-stages', 11, 'Somebody tries to move a change that is already "Rejected". What does the engine answer?', '["It refuses: A closed change is final.", "It refuses: An approver has rejected this change. It cannot be implemented.", "It refuses because the stage leads nowhere: A rejected change is final.", "It allows a move back to \"Review\"."]'::jsonb, 2, '"Rejected" is one of the 3 stages that lead nowhere. The gate refusal about a rejecting approver is a different sentence, about a rejected approval row on a live change.'),
  ('riskchange', 'intermediate', 'module', 'm01-a-change-and-its-stages', 12, 'Which change types must carry an expiry date?', '["\"Temporary\" and \"Emergency\".", "\"Temporary\" alone.", "Every type.", "\"Emergency\" alone."]'::jsonb, 0, 'The types that must carry an expiry date are "Temporary" and "Emergency". A "Permanent" change carries none and its expiry state reads "Permanent change".'),
  ('riskchange', 'intermediate', 'module', 'm01-a-change-and-its-stages', 13, 'The refusal "A change in Draft can only move to Screening, Cancelled." names two stages. Where do they come from?', '["The stages this change has already passed through, most recent first.", "The stages whose approval sets are complete for this change on the day it was asked.", "The row of legal next stages for \"Draft\", in the order the row lists them.", "The workflow order of all eight stages, starting from the one after \"Draft\"."]'::jsonb, 2, 'The sentence is the row: it names the stage the change is in and every move that stage allows. That is why a user can act on it without opening the stage table.'),
  ('riskchange', 'intermediate', 'module', 'm01-a-change-and-its-stages', 14, '"Cancelled" appears in which rows of the stage table?', '["Only the rows for \"Screening\", \"Review\" and \"Approval\".", "Every active row, from \"Draft\" through \"Implementation\".", "Every row, the three stages that lead nowhere included, so any record can be withdrawn.", "Only the \"Draft\" row, before any work has been spent on the change."]'::jsonb, 1, 'Withdrawing a change is open while the work is live, so all five active rows carry it. The three terminal rows read none.'),
  ('riskchange', 'intermediate', 'module', 'm01-a-change-and-its-stages', 15, 'A change in "Draft" has every approval level signed and every action complete. Can it move straight to "Approval"?', '["Yes, because a complete approval set is what \"Approval\" checks for.", "Yes, provided the change is of the type \"Emergency\".", "No, because the approval set has to be emptied first.", "No. The \"Draft\" row lists only \"Screening\" and \"Cancelled\", and no signature or action makes a move legal that the row leaves out."]'::jsonb, 3, 'A move is a question of two stages. The engine answers this one "A change in Draft can only move to Screening, Cancelled." whatever the rows and actions say.'),
  ('riskchange', 'intermediate', 'module', 'm02-approval-levels', 1, 'Where does the engine get the approval levels a change needs?', '["From a setting on the change type that fixes how many levels each type needs.", "From the approval rows themselves: whatever distinct levels appear on the rows attached to the change.", "From the risk level the change carries, one level for each band above \"Low\".", "From a fixed ladder of three levels that every change passes."]'::jsonb, 1, 'The engine keeps no separate list of levels. Every distinct level present must carry at least one Approved row, and no row at any level may be Rejected.'),
  ('riskchange', 'intermediate', 'module', 'm02-approval-levels', 2, 'An approval set carries rows at levels 1 and 3 and nothing at level 2; only level 1 has signed. How does the engine read it?', '["Levels 1, 2, 3; outstanding 2, 3.", "Levels 1, 3; complete yes.", "Refused as a malformed set, because a level 2 row has to sit between them.", "Levels 1, 3; outstanding 3; complete no."]'::jsonb, 3, 'A missing level is not invented. The levels are whatever the rows say, so a change that needs a level 2 signature needs a level 2 row somebody has added.'),
  ('riskchange', 'intermediate', 'module', 'm02-approval-levels', 3, 'An approval row carries no level at all. How is it read?', '["It counts as level 1.", "It is left out when the levels are read, like a row that is not on the set.", "It forms a separate unnamed level, which is outstanding until it signs.", "It counts as the highest level present anywhere on the same set."]'::jsonb, 0, 'A row with no level counts as level 1. A set holding one such row, signed, reads levels 1, outstanding none, complete yes.'),
  ('riskchange', 'intermediate', 'module', 'm02-approval-levels', 4, 'Two people are asked to approve at level 2, and one of them has signed. Level 1 has signed too. What does the set read?', '["Levels 1, 2; outstanding 2; complete no, until both rows at level 2 read Approved.", "Levels 1, 2; outstanding none; complete no, because a Pending row is left.", "Levels 1, 2; outstanding none; complete yes.", "Levels 1, 2, 2; outstanding 2; complete no."]'::jsonb, 2, 'One Approved row signs a level. The engine does not read a level as a vote that needs every row, so a Pending second signer leaves the level signed.'),
  ('riskchange', 'intermediate', 'module', 'm02-approval-levels', 5, 'A set holds one row, and its status is "Delegated". How does the engine read it?', '["Levels 1; outstanding none; complete yes, because delegating hands the signature on.", "Levels none; outstanding none; complete no, since a Delegated row is no row at all.", "Level 1 stays outstanding, so complete no.", "Levels 1; outstanding none."]'::jsonb, 2, 'A "Delegated" row is not an "Approved" row, so its level stays outstanding. Only "Approved" signs a level.'),
  ('riskchange', 'intermediate', 'module', 'm02-approval-levels', 6, 'Every level on a set has an Approved row, and one other row on it reads "Rejected". What does the engine read?', '["Outstanding none; rejected rows 1; complete no, because a rejection anywhere makes the set incomplete.", "Outstanding none; rejected rows 1; complete yes, because every level has signed.", "Outstanding 2; rejected rows 1; complete no.", "Outstanding none; rejected rows 0; complete yes."]'::jsonb, 0, 'The rule has two halves: every level signed, and no row at any level Rejected. The empty outstanding list satisfies the first half only.'),
  ('riskchange', 'intermediate', 'module', 'm02-approval-levels', 7, 'A change whose set has every level signed and one rejection is asked to move into "Implementation". Which sentence refuses it?', '["Approval level 2 has not signed yet.", "An approver has rejected this change. It cannot be implemented.", "A rejected change is final.", "No approvers have been assigned, so there is nothing to approve. Add the approval levels this change needs."]'::jsonb, 1, 'This refusal names a decision already made, and no further signature clears it while the rejected row sits on the set. "A rejected change is final." is about the Rejected stage.'),
  ('riskchange', 'intermediate', 'module', 'm02-approval-levels', 8, 'A change carries no approval rows at all. Is its approval set complete?', '["Yes, nothing is outstanding.", "Yes, for a Permanent change, which needs no levels unless rows are added.", "It cannot be read, so the engine returns no answer for the set at all.", "No. An empty set is incomplete."]'::jsonb, 3, 'The empty set reads levels none, outstanding none, rejected rows 0, complete no. A check that only asks whether anything is outstanding or rejected would let it through.'),
  ('riskchange', 'intermediate', 'module', 'm02-approval-levels', 9, 'What does the engine say when a change with no approval rows is asked to move into "Implementation"?', '["Approval level 1 has not signed yet.", "No approvers have been assigned, so there is nothing to approve. Add the approval levels this change needs.", "Choose the approver.", "The approval set on this change is complete, and it is allowed into Implementation with nothing to sign."]'::jsonb, 1, 'Because the engine reads levels from the rows, it cannot know how many a change should have. It can know that a change with no rows has not been through approval, and it refuses to treat that as approved.'),
  ('riskchange', 'intermediate', 'module', 'm02-approval-levels', 10, 'ES-01 is in "Approval" with levels 2 and 3 unsigned. What does the gate into "Implementation" answer?', '["It refuses: Approval levels 2 and 3 have not signed yet.", "It refuses: Approval level 1 has not signed yet.", "It allows it on level 1, the way the gate treats a change once its first level has signed.", "It refuses: No approvers have been assigned."]'::jsonb, 0, 'The sentence is built from the outstanding list, so it tells the user which levels to chase. ES-01 is Permanent, so every level must sign.'),
  ('riskchange', 'intermediate', 'module', 'm02-approval-levels', 11, 'Of the four approval statuses, which ones sign a level?', '["\"Approved\" and \"Delegated\", since a delegation passes the signature to a colleague.", "\"Approved\" and \"Pending\", once the row has been assigned to a named approver.", "\"Approved\" alone.", "Any status other than \"Rejected\"."]'::jsonb, 2, 'The statuses are "Pending", "Approved", "Rejected" and "Delegated", and only one of them signs. "Pending" and "Delegated" rows leave their level outstanding.'),
  ('riskchange', 'intermediate', 'module', 'm02-approval-levels', 12, 'An organisation wants two named people to sign before a change goes in. How must the rows be built for the engine to require both?', '["Put both at the same level; one level with two rows needs both to read Approved.", "Put both at the same level and mark one \"Delegated\" to the other.", "Put one at level 1 and leave the other row''s level blank so it counts separately.", "Put them at two different levels."]'::jsonb, 3, 'Two rows at one level mean either of these may sign for it. Two rows at different levels mean both levels must sign. A blank level lands on level 1.'),
  ('riskchange', 'intermediate', 'module', 'm02-approval-levels', 13, 'An Emergency change has level 1 signed and a Rejected row at level 2. Can it go into "Implementation" on the emergency route?', '["Yes. The route asks for level 1 alone, and level 2 is left to ratify later.", "No. The route needs level 1 signed and nobody having rejected it.", "Yes, and the Rejected row reads as awaiting ratification once it is in.", "No, because an Emergency change needs every level signed."]'::jsonb, 1, 'The emergency route shortens the wait for signatures. It does not step over a rejection, which stops the gate for every type.'),
  ('riskchange', 'intermediate', 'module', 'm02-approval-levels', 14, 'A set reports outstanding none and rejected rows 0. What must you still check before calling it complete?', '["That there are rows at all, since a set with no approval rows reports the same two answers and reads complete no.", "That every row has a level, since a blank level makes the set incomplete.", "That the change is Permanent, since other types are read differently.", "Nothing: those two answers are the whole rule."]'::jsonb, 0, 'Look at the row count before the outstanding list. An empty outstanding list is good news only when there are rows to be outstanding.'),
  ('riskchange', 'intermediate', 'module', 'm02-approval-levels', 15, 'The word "Rejected" names both an approval status and a stage. What does a Rejected approval row do to a live change?', '["It moves the change to \"Rejected\".", "It makes the change final.", "It cancels every other row on the set, signed ones included.", "It stops the gate into \"Implementation\"."]'::jsonb, 3, 'A rejected row is a status on one row and stops the gate. "Rejected" as a stage is terminal and answers "A rejected change is final." Name which one you mean.'),
  ('riskchange', 'intermediate', 'module', 'm03-segregation-of-duties', 1, 'ES-01 was raised by u-chika. Somebody tries to assign u-chika as one of its approvers. What does the engine answer?', '["It allows it, provided u-chika is assigned at a level above the first.", "It allows the assignment and refuses only when u-chika tries to decide.", "It refuses: Only the person this approval is assigned to can decide it.", "It refuses: The originator of a change cannot approve it. Choose somebody independent of the change."]'::jsonb, 3, 'Independence is checked at assignment first. The second half of the sentence names the way forward: choose somebody independent of the change.'),
  ('riskchange', 'intermediate', 'module', 'm03-segregation-of-duties', 2, 'An approval on ES-01 is assigned to nobody. What does the engine answer?', '["It allows it, and anyone independent may then decide the approval.", "It refuses: Choose the approver.", "It allows it and reads the row as \"Delegated\".", "It refuses: No approvers have been assigned, so there is nothing to approve."]'::jsonb, 1, 'An approval assigned to nobody would have no one who could decide it, so the assignment is refused with the shortest sentence in the module.'),
  ('riskchange', 'intermediate', 'module', 'm03-segregation-of-duties', 3, 'Why is u-halima allowed as an approver on ES-01?', '["u-halima did not raise ES-01, so u-halima is independent of the change.", "u-halima is the level 2 assignee on ES-01, and only an assignee may be added as an approver.", "u-halima is senior to u-chika.", "u-halima raised ES-01 and knows it."]'::jsonb, 0, 'The refusal names one person to keep off the change: its originator. u-chika raised ES-01; u-halima did not, and the engine allows u-halima as an independent approver.'),
  ('riskchange', 'intermediate', 'module', 'm03-segregation-of-duties', 4, 'ES-01''s level 2 approval is assigned to u-emeka. u-halima, who is independent of the change, tries to decide it. What does the engine answer?', '["It allows it, because u-halima is independent of ES-01 and could have been assigned.", "It refuses: The originator of a change cannot approve it. Choose somebody independent of the change.", "It refuses: Only the person this approval is assigned to can decide it. If they are unavailable, reassign it.", "It allows it and records the row as \"Delegated\" from u-emeka to u-halima."]'::jsonb, 2, 'Independence decides who may be assigned. Assignment decides who may decide. An approval belongs to the person it is assigned to.'),
  ('riskchange', 'intermediate', 'module', 'm03-segregation-of-duties', 5, 'Nobody is signed in when a decision is attempted on ES-01''s level 2 approval, which is assigned to u-emeka. Which other attempt meets the same refusal sentence word for word?', '["Assigning nobody as the approver on ES-01.", "u-chika, the originator, deciding an approval somebody assigned to u-chika.", "Moving a change with no approval rows at all into \"Implementation\".", "u-halima trying to decide that same approval."]'::jsonb, 3, 'Both are refused with: Only the person this approval is assigned to can decide it. If they are unavailable, reassign it. Neither nobody nor u-halima is u-emeka. Assigning nobody meets "Choose the approver." and the originator meets "The originator of a change cannot approve it."'),
  ('riskchange', 'intermediate', 'module', 'm03-segregation-of-duties', 6, 'A record arrives with the originator already assigned to decide an approval on their own change. The originator decides it. What does the engine answer?', '["Refused: an originator never decides, even as assignee.", "It allows it, because the originator is the assignee on that row and only the assignee decides an approval.", "It refuses: Only the person this approval is assigned to can decide it. If they are unavailable, reassign it.", "It allows it once a second approver signs."]'::jsonb, 0, 'The originator rule is checked at the decision as well as at the assignment, so the originator is refused as an approver and as a decider, even when assigned.'),
  ('riskchange', 'intermediate', 'module', 'm03-segregation-of-duties', 7, 'Why does the engine check independence at the decision as well as at the assignment?', '["So the originator may sign a level once an independent approver has signed the level first.", "So that a row assigned some other way still cannot be signed by the wrong person.", "So an absent approver''s row can be decided by the originator.", "So a Delegated row can be signed off."]'::jsonb, 1, 'Holding the rule at both moments means an assignment made outside the engine''s own check still meets the originator refusal when somebody tries to decide it.'),
  ('riskchange', 'intermediate', 'module', 'm03-segregation-of-duties', 8, 'Somebody tries a second decision on a row that already reads "Approved". Which refusal follows?', '["It allows it, and the second decision replaces the first one on the row.", "It allows it when the assignee is the person deciding.", "It refuses: This approval is already approved.", "It refuses: Choose the approver."]'::jsonb, 2, 'A decision is made once, by anyone, the assignee included. "Approved" and "Rejected" are decisions, and a decision stands.'),
  ('riskchange', 'intermediate', 'module', 'm03-segregation-of-duties', 9, 'Why does it matter that an approval already "Rejected" cannot be decided again?', '["Because the Rejected stage is final, and the row takes the stage''s rule from it.", "Because a second decision on a row always has to be taken by the originator.", "Because a rejected row is removed from the set once it has been decided.", "The rejection would otherwise be overwritten."]'::jsonb, 3, 'The engine refuses with "This approval is already rejected." If a second decision were allowed, the rejected row would become approved, the set would read complete, and the record would lose the objection.'),
  ('riskchange', 'intermediate', 'module', 'm03-segregation-of-duties', 10, 'u-emeka tries to decide an approval whose status is "Delegated". What does the engine answer?', '["It allows it, because u-emeka is the assignee on the row.", "Refused as already decided: This approval is already delegated.", "It allows it and the level reads signed.", "It refuses: Choose the approver, because a Delegated row has no assignee left on it."]'::jsonb, 1, '"Delegated" is a status a row can carry and nothing more. It signs nothing, its level stays outstanding, and deciding it is refused as already decided.'),
  ('riskchange', 'intermediate', 'module', 'm03-segregation-of-duties', 11, 'What is decision D1, and when was it taken?', '["Owner policy under AS15, decided on 2026-09-18: an approval is decided only by its assignee, never by the change originator, and an absence is covered by reassigning it.", "Owner policy under AS15, decided on 2026-09-18: an absent approver''s level may be signed by any member independent of the change.", "An engine default decided on 2026-10-01: the originator signs level 1 and independent members sign the rest.", "Owner policy under AS15: a Delegated row signs its level."]'::jsonb, 0, 'Covering an absence is part of the decision itself, the answer to the worry that strict assignment would leave changes stuck while somebody is away.'),
  ('riskchange', 'intermediate', 'module', 'm03-segregation-of-duties', 12, 'u-emeka, the level 2 assignee on ES-01, is unavailable. What route does the engine''s refusal name?', '["Let u-halima decide it, since u-halima is independent of the change.", "Record the row as \"Delegated\", which signs the level.", "Reassign the approval.", "Let u-chika decide it, as the person who knows the change best."]'::jsonb, 2, 'The assignee refusal ends: If they are unavailable, reassign it. A "Delegated" row signs nothing, and u-chika is the originator.'),
  ('riskchange', 'intermediate', 'module', 'm03-segregation-of-duties', 13, 'The app moves ES-01''s level 2 approval away from u-emeka. On which new assignee does the engine still refuse the decision?', '["u-halima, because the approval was first assigned to u-emeka and stays with them.", "u-halima, because a person who was not on the original set can never decide.", "Any member at all, because the engine holds no rule for moving an approval.", "u-chika, who raised ES-01."]'::jsonb, 3, 'The engine checks the decision as well as the assignment. The originator deciding an approval somebody assigned to them is refused: The originator of a change cannot approve it.'),
  ('riskchange', 'intermediate', 'module', 'm03-segregation-of-duties', 14, 'Searching the engine''s 34 exports, how many functions have a name that mentions reassigning or delegating?', '["34, one for each export, because every function in the engine can hand an approval to another member.", "0. How an approval moves to somebody else is the app''s and the database''s business.", "1, the function that reads a Delegated row as signed.", "0, so reassignment is refused by the engine as illegal."]'::jsonb, 1, 'The engine holds no rule for moving an approval. It still refuses the originator at the decision, even when somebody assigned the approval to them.'),
  ('riskchange', 'intermediate', 'module', 'm03-segregation-of-duties', 15, 'A report says: "The engine lets a decided approval be reopened by the assignee." What does the digest support?', '["The report is right for Rejected rows, which the assignee can reopen once to answer the objection that was raised.", "The report is right, because only the assignee decides.", "None of it. The engine holds no rule for reopening, and a decided approval is refused as already decided.", "The report is right while the change is still in \"Approval\", since a reopened row goes back to Pending there."]'::jsonb, 2, 'Searching for reopening, revisiting, undoing, revoking or withdrawing a decision finds 0 functions. A decided approval is refused as already approved or already rejected.'),
  ('riskchange', 'intermediate', 'module', 'm04-actions-and-the-two-gates', 1, 'Which two action statuses does the engine count as finished?', '["\"Complete\" alone, since a cancelled action is work nobody did.", "\"Complete\" and \"In progress\".", "\"Complete\" and \"Cancelled\".", "\"Cancelled\" alone."]'::jsonb, 2, 'The statuses are "Open", "In progress", "Complete" and "Cancelled". An action decided to be unnecessary is no longer work anyone owes, and work that has started has not ended.'),
  ('riskchange', 'intermediate', 'module', 'm04-actions-and-the-two-gates', 2, 'An unfinished action blocks one gate or the other according to its type. Which gate does an unfinished "Pre-implementation" action block?', '["Only the first gate, the move from \"Approval\" onto the facility.", "The gate into the Closed stage, along with the other two action types.", "Both gates.", "Neither gate."]'::jsonb, 0, 'Pre-implementation actions block the gate into "Implementation"; Implementation and Post-implementation actions block the gate into the Closed stage. Each gate reads the action types it names.'),
  ('riskchange', 'intermediate', 'module', 'm04-actions-and-the-two-gates', 3, 'ES-01 has every level signed and one Pre-implementation action still "Open". What does the gate into "Implementation" answer?', '["It allows it, because the action can be finished once the change is on the facility.", "It refuses: Approval levels 2 and 3 have not signed yet.", "It refuses: 1 implementation or post-implementation action still open.", "It refuses: 1 pre-implementation action still open. They exist to be done before the change goes in."]'::jsonb, 3, 'Condition 1, the approvals, is cleared. Condition 2 fails on the one open Pre-implementation action; ES-01 also carries AC-02, which is "Complete" and blocks nothing.'),
  ('riskchange', 'intermediate', 'module', 'm04-actions-and-the-two-gates', 4, 'ES-02 is in "Implementation" with its Post-implementation action AC-03 "In progress". What does the gate into the Closed stage answer?', '["It allows it, because an action in progress has already been started.", "It refuses: 1 implementation or post-implementation action still open.", "It refuses: 1 pre-implementation action still open.", "It allows it: that work is done after closing."]'::jsonb, 1, '"In progress" is unfinished. Once AC-03 reads "Complete" the engine allows ES-02 into the Closed stage.'),
  ('riskchange', 'intermediate', 'module', 'm04-actions-and-the-two-gates', 5, 'Withdrawal instead: ES-02 is moved to "Cancelled" while AC-03 is unfinished. What is the verdict?', '["It refuses: 1 implementation or post-implementation action still open.", "It refuses, because a change in Implementation can only move to Closed.", "It allows it: no action blocks a cancellation.", "It allows it once AC-03 is \"Cancelled\" too."]'::jsonb, 2, 'The action gate guards the Closed stage, which claims the work is done. Cancelling makes no such claim, and blocking it would trap a change nobody wants in "Implementation".'),
  ('riskchange', 'intermediate', 'module', 'm04-actions-and-the-two-gates', 6, 'A Temporary change''s expiry field reads "after the turnaround". It is asked to move into "Implementation" with every level signed. What does the engine answer?', '["It refuses: A temporary change needs an expiry date before it is implemented. Without one it is a permanent change nobody decided to make.", "It allows it, because the phrase names a real event on the site that everyone can see.", "It allows it and reads the expiry state as \"Within expiry\".", "It refuses: Approval level 1 has not signed yet."]'::jsonb, 0, 'The engine treats an unreadable expiry exactly as it treats a blank. The same refusal is given for a Temporary change with no expiry date at all.'),
  ('riskchange', 'intermediate', 'module', 'm04-actions-and-the-two-gates', 7, 'A Temporary change in "Approval" carries a readable expiry of 2026-09-30. With every level signed, it is asked into "Implementation" on 2026-10-01. What does the gate answer?', '["It refuses, because an expiry date that has already passed cannot be implemented.", "It refuses, because a Temporary change needs an Emergency approval once its date is past.", "It allows it and reads the change as \"Closed out\" on 2026-10-01.", "It allows it."]'::jsonb, 3, 'The gate asks only that the expiry can be read; it does not ask that it lies ahead. Once in "Implementation" the same change reads "Expired" on 2026-10-01.'),
  ('riskchange', 'intermediate', 'module', 'm04-actions-and-the-two-gates', 8, 'A Temporary change is already in "Implementation" with an expiry that reads "after the turnaround". What is its expiry state?', '["\"Expired\", because no date can be shown to lie ahead.", "\"No expiry\", since the date cannot be read.", "\"Within expiry\", until the turnaround ends.", "\"Expiring soon\"."]'::jsonb, 1, 'An unreadable expiry is no expiry, so such a change can never read "Expired". That is why the gate insists on a readable date before the change goes in.'),
  ('riskchange', 'intermediate', 'module', 'm04-actions-and-the-two-gates', 9, 'An Emergency change in "Implementation" still has level 2 unsigned. It is asked to move into the Closed stage. What does the engine answer?', '["It allows it, because an Emergency change went in on its first level and needs nothing more.", "It refuses: Approval level 2 has not signed yet.", "It refuses: Approval level 2 has not ratified this emergency change. It cannot close until every level has signed.", "It allows it if its implementation date is within the last 7 days."]'::jsonb, 2, 'Into the Closed stage an Emergency change needs every level signed, however long ago it went in. The later signatures ratify a decision already acted on.'),
  ('riskchange', 'intermediate', 'module', 'm04-actions-and-the-two-gates', 10, 'The ESANMI summary reads openActions 4 on 2026-10-01. Which four actions are they?', '["AC-01, AC-03, AC-05 and AC-09.", "AC-01, AC-03, AC-05 and AC-06.", "AC-01, AC-03, AC-06 and AC-07, the actions still marked Open or In progress, whatever their change.", "AC-03, AC-05, AC-07 and AC-09."]'::jsonb, 0, 'Finished statuses leave the count, and so do actions on finished changes: AC-06 on ES-06, which is Closed, and AC-07 on ES-09, which is "Cancelled". AC-09, whose change is unknown, stays in.'),
  ('riskchange', 'intermediate', 'module', 'm04-actions-and-the-two-gates', 11, 'AC-06 is "Open" and was due on 2026-09-01. Why is it in neither openActions nor overdueActions on 2026-10-01?', '["Its due date has aged out of both counts.", "Post-implementation actions are left out of the open count until their change has closed.", "An \"Open\" action counts once it is \"In progress\".", "Its change, ES-06, is in the Closed stage, so it is finished and locked."]'::jsonb, 3, 'The engine reads the action''s change as well as the action. The same holds for AC-07 on ES-09, which is "Cancelled", and for an Open action on the "Rejected" ES-11, which reads openActions 0.'),
  ('riskchange', 'intermediate', 'module', 'm04-actions-and-the-two-gates', 12, 'AC-09 names change ES-99, which is not in the ESANMI register. How does the summary treat it?', '["It skips it: its change is unknown, so the work cannot be placed.", "It counts it, in openActions and in overdueActions.", "It counts it in openActions and leaves it out of overdueActions.", "It refuses to summarise the register until ES-99 is supplied."]'::jsonb, 1, 'Not knowing the parent is no reason to hide the work. AC-09 is due 2026-09-30, -1 days on 2026-10-01, so it is also overdue.'),
  ('riskchange', 'intermediate', 'module', 'm04-actions-and-the-two-gates', 13, 'One open action is due on the as-of date itself, 2026-10-01. What do the counts read on that date?', '["openActions 1, overdueActions 1, since the day has arrived.", "openActions 0, overdueActions 1, since the action has fallen due.", "openActions 1, overdueActions 0.", "openActions 0, overdueActions 0, until the day itself has passed."]'::jsonb, 2, 'An action is overdue when its due date has PASSED, days until below zero. Due the day before, 2026-09-30, reads openActions 1, overdueActions 1.'),
  ('riskchange', 'intermediate', 'module', 'm04-actions-and-the-two-gates', 14, 'Two actions in the ESANMI log are overdue on 2026-10-01. Name them with their days until.', '["AC-01 at -3 days and AC-09 at -1 days.", "AC-01 at -3 days and AC-06 at -30 days.", "AC-06 and AC-07, the two furthest behind.", "AC-03 and AC-05."]'::jsonb, 0, 'AC-01 is due 2026-09-28 and AC-09 2026-09-30. AC-03 and AC-05 fall due after the as-of date, and AC-06 and AC-07 sit on finished changes.'),
  ('riskchange', 'intermediate', 'module', 'm04-actions-and-the-two-gates', 15, 'Where does late work on a change already in "Implementation" show up on 2026-10-01?', '["As the change''s own overdue flag, read against its target date.", "As overdue actions.", "As \"Ratification overdue\" on every type.", "As \"Expired\"."]'::jsonb, 1, 'A change''s own overdue flag is read only before it is on the facility. ESANMI holds 5 changes in "Implementation", 5 past their target, and none reads overdue.'),
  ('riskchange', 'intermediate', 'module', 'm05-temporary-and-emergency-change', 1, 'Screening and Review are stages before the facility. For a Temporary change in "Review" whose expiry was 2026-09-30, what does the engine print on 2026-10-01?', '["\"Expired\", because the expiry date is already behind the as-of date on 2026-10-01.", "\"No expiry\", because a change that is not in effect cannot expire.", "\"Expiring soon\", until the change goes into Implementation.", "\"Closed out\"."]'::jsonb, 1, 'Only a change in effect can expire. A temporary change still in Screening or Review is not running anywhere, so its expiry date is a plan and it is not counted expired.'),
  ('riskchange', 'intermediate', 'module', 'm05-temporary-and-emergency-change', 2, 'Which expiry state belongs to a finished temporary change in the Closed stage whose date lies behind the as-of date of 2026-10-01?', '["\"Expired\", because a closed change is in effect and its date has passed.", "\"No expiry\", because a closed change is terminal and no longer running.", "\"Permanent change\", because it stayed on the facility.", "\"Closed out\"."]'::jsonb, 3, 'The Closed stage is in effect and terminal. A closed temporary change reads "Closed out" and is not counted expired, so a change taken through to the Closed stage is not reported as expired for ever after.'),
  ('riskchange', 'intermediate', 'module', 'm05-temporary-and-emergency-change', 3, 'ES-10 is a Temporary change in "Screening" with an expiry of 2026-09-01. What does it read on 2026-10-01, and is it counted expired?', '["\"No expiry\", and it is not counted expired, because nothing went onto the facility.", "\"Expired\", counted expired, because the date is behind 2026-10-01 and the change carries a Temporary type.", "\"Expired\", though left out of the expired count until the change reaches Implementation on the plant.", "\"Within expiry\", uncounted."]'::jsonb, 0, 'The date passed while the change was still being screened. The ESANMI summary reads expired 1 on 2026-10-01, and that one is ES-03.'),
  ('riskchange', 'intermediate', 'module', 'm05-temporary-and-emergency-change', 4, 'Which three expiry states come from the record and do not move with the as-of date?', '["\"Expired\", \"Expiring soon\" and \"Within expiry\".", "\"Permanent change\", \"Closed out\" and \"Expired\", since an expired change stays expired on every later date.", "\"No expiry\", \"Permanent change\" and \"Closed out\".", "\"No expiry\", \"Permanent change\" and \"Within expiry\", since a date far off is read as no date."]'::jsonb, 2, '"Expired", "Expiring soon" and "Within expiry" move with the date and appear only on a change in effect with a readable expiry. Quote those three with the date they are true on.'),
  ('riskchange', 'intermediate', 'module', 'm05-temporary-and-emergency-change', 5, 'Counting inclusively, where does an expiry of 2026-10-15 fall for a Temporary change in "Implementation" read on 2026-10-01?', '["\"Within expiry\": 14 days away, and \"Expiring soon\" starts below 14.", "\"Expiring soon\": 14 days away, and the lead of 14 days is counted inclusively.", "\"Expiring soon\": 15 days away.", "\"Within expiry\": 15 days away."]'::jsonb, 1, 'EXPIRY_LEAD_DAYS is 14, counted inclusively, so the fourteenth day is inside the lead. An expiry of 2026-10-16, 15 days away, reads "Within expiry" on the same date.'),
  ('riskchange', 'intermediate', 'module', 'm05-temporary-and-emergency-change', 6, 'The expiry of a Temporary change in effect is 2026-10-16. Which expiry state does the engine give it on 2026-10-01?', '["\"Expiring soon\", because 15 days is still inside a lead of 14 counted inclusively.", "\"Expiring soon\", because the expiry falls in the same calendar month.", "\"No expiry\", because an expiry outside the lead is not read.", "\"Within expiry\"."]'::jsonb, 3, '2026-10-16 is 15 days from 2026-10-01, one day past the lead. "Counted inclusively" takes in the fourteenth day and no more.'),
  ('riskchange', 'intermediate', 'module', 'm05-temporary-and-emergency-change', 7, 'Due today: a temporary change on the plant expires on 2026-10-01 itself. Which state and days until does the engine print that day?', '["\"Expired\", at 0 days, because the expiry day has arrived.", "\"Expired\", at -1 days.", "\"Expiring soon\", at 0 days.", "\"Within expiry\", at 0 days."]'::jsonb, 2, 'Only a negative count of days reads "Expired"; an expiry of 2026-09-30 is -1 and reads "Expired". A date equal to the as-of date has not passed.'),
  ('riskchange', 'intermediate', 'module', 'm05-temporary-and-emergency-change', 8, 'An Emergency change in "Approval" has level 1 signed and level 2 pending, and nothing is rejected. A Permanent change has the same signatures. What does the gate into "Implementation" answer for each?', '["It allows the Emergency change and refuses the Permanent one: Approval level 2 has not signed yet.", "It refuses both: Approval level 2 has not signed yet.", "It allows both, because level 1 has signed on each.", "It allows the Permanent one only."]'::jsonb, 0, 'The signatures are identical and only the type differs. An Emergency change goes in once its first level has signed and nobody has rejected it; a Permanent change needs every level.'),
  ('riskchange', 'intermediate', 'module', 'm05-temporary-and-emergency-change', 9, 'Nothing has signed at level 1 on an Emergency change waiting in "Approval". Which sentence refuses it at the gate?', '["It allows it, because the emergency route defers every signature until after the change goes in.", "It refuses: An emergency change can go in once approval level 1 has signed, with the rest ratified within 7 days. Level 1 has not signed yet.", "It refuses: Approval levels 1 and 2 have not signed yet.", "It allows it and reads the ratification state as \"Awaiting ratification\" for 7 days."]'::jsonb, 1, 'One signature is reduced authority; none is no authority. The refusal states the whole policy, decision Q9 under AS15: level 1 up front, the rest ratified within 7 days.'),
  ('riskchange', 'intermediate', 'module', 'm05-temporary-and-emergency-change', 10, 'An Emergency change in "Implementation" with level 2 unsigned went in on 2026-09-24. What does it read on 2026-10-01?', '["Due 2026-09-30, \"Ratification overdue\", since 7 days have gone by.", "Due 2026-10-01, \"Ratification overdue\", because the due date has arrived.", "Due 2026-10-02, \"Awaiting ratification\", counted from the day after it went in.", "Due 2026-10-01, \"Awaiting ratification\"."]'::jsonb, 3, 'EMERGENCY_RATIFY_DAYS is 7, added to the actual implementation date. Day seven is still inside the window, because a due date equal to the as-of date has not passed.'),
  ('riskchange', 'intermediate', 'module', 'm05-temporary-and-emergency-change', 11, 'Level 2 is still unsigned on an Emergency change implemented on 2026-09-23. Give its ratification due date and state on 2026-10-01.', '["Due 2026-09-30, \"Ratification overdue\", because the due date is the day before the as-of date.", "Due 2026-10-01, \"Awaiting ratification\", because the window of 7 days runs from the day after it went in.", "Due 2026-09-30, \"Awaiting ratification\".", "Due 2026-09-30, \"Ratified\"."]'::jsonb, 0, 'Implemented 2026-09-23 plus 7 days is 2026-09-30. Day eight is outside the window, and level 2 is still unsigned.'),
  ('riskchange', 'intermediate', 'module', 'm05-temporary-and-emergency-change', 12, 'No implementation date is recorded for an Emergency change on the plant whose level 2 is unsigned. Which due date and ratification state does the engine give on 2026-10-01?', '["Due null, \"Awaiting ratification\", because no window has started yet to run out.", "Due 2026-10-08, \"Awaiting ratification\", counting from the as-of date instead.", "Due null, \"Ratification overdue\".", "Due null, \"Not required\"."]'::jsonb, 2, 'The window cannot be shown to be open, so it fails closed. ES-12 in the ESANMI register is this case: due null, "Ratification overdue" on 2026-10-01.'),
  ('riskchange', 'intermediate', 'module', 'm05-temporary-and-emergency-change', 13, 'What ratification state does a Temporary change read?', '["\"Awaiting ratification\" while it is in effect, until every level has signed.", "\"Not required\", because ratification belongs to the emergency route alone.", "\"Ratified\" once its expiry date has passed.", "\"Ratification overdue\"."]'::jsonb, 1, 'The four ratification states are "Not required", "Awaiting ratification", "Ratification overdue" and "Ratified". Only an Emergency change is ratified.'),
  ('riskchange', 'intermediate', 'module', 'm05-temporary-and-emergency-change', 14, 'Every approval level has now signed on an Emergency change that went in on 2026-09-01. Name its ratification state as of 2026-10-01.', '["\"Ratification overdue\", due 2026-09-08, because it went in 30 days before the as-of date.", "\"Awaiting ratification\", because the change is still in \"Implementation\".", "\"Not required\", because nothing is left to sign.", "\"Ratified\"."]'::jsonb, 3, 'Every level signed reads "Ratified", however long ago the change went in. With level 2 unsigned the same date gives due 2026-09-08, "Ratification overdue".'),
  ('riskchange', 'intermediate', 'module', 'm05-temporary-and-emergency-change', 15, 'The ESANMI summary reads ratificationOverdue 2 on 2026-10-01. Which two changes, and why does each read overdue?', '["ES-05, whose due date 2026-09-27 has passed, and ES-12, whose due date is null because no implementation date is recorded.", "ES-04 and ES-05, both past their due dates of 2026-10-03 and 2026-09-27.", "ES-05 and ES-03, the two changes past their dates.", "ES-05 alone, counted twice."]'::jsonb, 0, 'ES-04 reads "Awaiting ratification", due 2026-10-03, which is ratificationPending 1. A reader who drops the row with a null due date misses ES-12.'),
  ('riskchange', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'Which changes does the total count in the ESANMI summary take in on 2026-10-01?', '["The live changes only, since finished changes are locked and leave the summary.", "Every change that has reached the facility, in \"Implementation\" or the Closed stage.", "The active changes plus those whose expiry state is \"Closed out\".", "Every row, whatever its stage."]'::jsonb, 3, 'Total counts every row, including the four finished changes ES-06, ES-07, ES-09 and ES-11. Active, a different count, reads 8.'),
  ('riskchange', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'Which change does byUrgency put first on 2026-10-01, and why?', '["ES-03, the one change that reads \"Expired\", because expired changes rank first.", "ES-08, the one change that reads overdue on its target date.", "ES-05, because its ratification is overdue.", "ES-12, because its due date is null."]'::jsonb, 0, 'byUrgency ranks expired changes first, then expiring soon, then overdue, then other live work, then everything finished. ES-03''s expiry of 2026-09-28 is behind the as-of date.'),
  ('riskchange', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'In byUrgency on 2026-10-01, ES-05 comes before ES-02. What decides that?', '["ES-05 is an Emergency change, and within any one rank Emergency changes come before Temporary ones.", "ES-05 reads \"Ratification overdue\", and an overdue ratification outranks an expiry on the list.", "Both read \"Expiring soon\", and ES-05''s expiry, 2026-10-10, is earlier than ES-02''s, 2026-10-14.", "ES-05''s target date is earlier, 2026-09-20 against 2026-09-26."]'::jsonb, 2, 'Within a rank the earlier expiry or target date comes first. ES-02''s target is also 2026-09-20, so a reader who sorted on the target could not separate them.'),
  ('riskchange', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'ES-08 is the one change that reads overdue in the ESANMI register on 2026-10-01. Why ES-08?', '["It is the one change whose actions are overdue on that date.", "It is in \"Review\", before the facility, and its target date of 2026-09-25 has passed.", "It has the earliest target date of any live change in the register on 2026-10-01.", "It is in \"Review\" and its expiry date has passed."]'::jsonb, 1, 'The overdue flag on a change is read against its target date and only in "Draft", "Screening", "Review" and "Approval". ES-08 is a Permanent change and carries no expiry.'),
  ('riskchange', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'awaitingApproval reads 1 on 2026-10-01, although ES-01 carries two Pending approval rows. Why 1?', '["It counts approval levels that are still outstanding, and ES-01 has one level left to sign.", "It counts Pending rows, and one of ES-01''s two rows is left out because it was delegated.", "It counts the changes carrying a Pending row, less the changes already in Implementation.", "It counts changes whose stage is \"Approval\"."]'::jsonb, 3, 'awaitingApproval counts changes whose STAGE is Approval, so ES-01 counts once. ES-01''s levels 2 and 3 are the ones the gate reports unsigned.'),
  ('riskchange', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'The ESANMI counts by risk level read "Low" 2, "Medium" 4, "High" 4, "Critical" 2. Which two changes are the "Critical" pair?', '["ES-04 and ES-12, both Emergency changes in \"Implementation\".", "ES-03 and ES-05, the two changes most urgent on 2026-10-01.", "ES-05 and ES-12, the two changes whose ratification reads overdue on 2026-10-01.", "ES-01 and ES-02, the two changes that head the stage order of the register."]'::jsonb, 0, 'Every row counts by risk level, finished changes included. ES-05 carries "High" and ES-03 "Medium", so urgency and risk level are separate readings.'),
  ('riskchange', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'expiringSoon reads 2 on 2026-10-01. Which two changes are behind it?', '["ES-02 and ES-04, the two in-effect changes with expiries still ahead.", "ES-02 and ES-05.", "ES-02 and ES-10, whose expiries fall within 14 days of 2026-10-01.", "ES-05 alone."]'::jsonb, 1, 'ES-02 expires 2026-10-14 and ES-05 2026-10-10, both inside the lead of 14 days counted inclusively. ES-04''s expiry of 2026-11-29 reads "Within expiry", and ES-10 is in "Screening".'),
  ('riskchange', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'ES-11 is "Rejected". Which reading does it give on 2026-10-01?', '["\"No expiry\", overdue yes, since its target of 2026-09-01 has passed.", "\"Permanent change\", overdue yes, and \"Not required\".", "\"Permanent change\" and \"Not required\", overdue no, and no open actions.", "\"Permanent change\" and \"Not required\", overdue no, with any Open action on it still counted as open work."]'::jsonb, 2, 'ES-11 is terminal and never in effect. A probe puts an Open action due 2026-09-26 on it and reads openActions 0, overdueActions 0.'),
  ('riskchange', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'ES-01 and ES-12 both show a null ratification due date. What does each null mean on 2026-10-01?', '["Both mean no window has started, so both read \"Not required\" until a date is recorded.", "Both mean the change is overdue for ratification, since neither can show a window open.", "ES-01 is awaiting ratification and ES-12 has been ratified, so neither has a date left.", "ES-01 needs no window; ES-12''s window cannot be counted."]'::jsonb, 3, 'ES-01 is Permanent and reads "Not required". ES-12 is an Emergency change with no implementation date and reads "Ratification overdue". Always read the null beside the state.'),
  ('riskchange', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'Where do the four finished changes sit in byUrgency on 2026-10-01?', '["Last: ES-07, ES-09, ES-06 and ES-11, after every live change.", "First, since finished changes need closing out.", "Mixed in by their target dates.", "Left out of the order entirely."]'::jsonb, 0, 'The order is ES-03, ES-05, ES-02, ES-08, ES-10, ES-01, ES-04, ES-12, ES-07, ES-09, ES-06, ES-11. Everything finished comes after the other live work.'),
  ('riskchange', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'ratificationPending reads 1 on 2026-10-01. Which change is it, and what is its due date?', '["ES-05, \"Awaiting ratification\", due 2026-09-27.", "ES-04, whose window runs to 2026-10-03.", "ES-12, \"Awaiting ratification\", with no due date because none was recorded.", "ES-04, \"Ratified\"."]'::jsonb, 1, 'ES-04''s due date is after the as-of date, so its window is open. ES-05 is past its due date and ES-12 has none; they make ratificationOverdue 2.'),
  ('riskchange', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'Before reading a change register, what does the capstone lesson say to write down first?', '["The number of changes in the register, so each count can be checked against the total.", "The type of every change, since the type decides every state.", "The as-of date, because every dated state is true on one date.", "The machine clock''s date, which the engine reads by default."]'::jsonb, 2, 'Every expiry state, ratification state and overdue flag is true on one date. The engines default to the machine clock, so the stated date is what makes an answer checkable.'),
  ('riskchange', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'The capstone lesson''s check for an open action runs in an order. Which order does it give?', '["Test the due date first, then skip anything more than 14 days past the as-of date, then skip Cancelled.", "Keep every Open or In progress action, then drop the ones whose change is unknown, then test the due date.", "Skip finished statuses, keep terminal changes that have open actions, then count anything due on the as-of date.", "Skip finished statuses, skip terminal changes, keep unknown changes, then test the due date."]'::jsonb, 3, 'Put the action log beside the change register. An open action is overdue only when its due date has passed, days until below zero; one due on the as-of date is not.'),
  ('riskchange', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'This tier met two owner decisions, both taken under AS15 on 2026-09-18. Which two, and what does each decide?', '["D1, that only the assignee decides an approval and never the originator, and Q9, the emergency route and its ratification window.", "D1, the stage table, and Q9, the lead of 14 days before an expiry.", "D1, the approval levels, and Q9, the no-rows refusal.", "Q9 alone, the emergency route."]'::jsonb, 0, 'D1 is segregation of duties, enforced by the database too, with an absence covered by reassigning. Q9 is reduced authority up front and full review after the event, within 7 days.'),
  ('riskchange', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'Which list does a rule read to decide that a change''s actions are no longer open work?', '["The in-effect list, since a change on the facility has finished its work.", "The terminal list: \"Closed\", \"Rejected\" and \"Cancelled\".", "The active list, read the other way round.", "The expiry states."]'::jsonb, 1, 'A finished and locked change takes its actions out of openActions. ESANMI shows it on AC-06 (ES-06, Closed) and AC-07 (ES-09, Cancelled), and a probe shows it on the Rejected ES-11.'),
  ('riskchange', 'intermediate', 'final', null, 1, 'A Temporary change was "Cancelled" while its expiry was still ahead; the date has since passed. What does it read on 2026-10-01?', '["\"Expired\", counted, because the date is behind 2026-10-01 on a type that carries an expiry.", "\"No expiry\", uncounted, because \"Cancelled\" sits outside the in-effect list.", "\"Closed out\", because a cancelled change is terminal.", "\"Permanent change\"."]'::jsonb, 1, 'Only "Implementation" and the Closed stage are in effect. A Temporary change in "Cancelled" one day past its expiry reads "No expiry" and is not counted expired.'),
  ('riskchange', 'intermediate', 'final', null, 2, 'Which moves does the stage table allow out of "Screening"?', '["\"Review\" and \"Cancelled\" only.", "\"Review\", \"Approval\" and \"Cancelled\", since a screened change may skip ahead.", "\"Review\", \"Rejected\" and \"Cancelled\", with no step back from a screened change.", "\"Review\", \"Rejected\", \"Cancelled\" and back to \"Draft\"."]'::jsonb, 3, 'Screening has four legal next stages. Screening, Review and Approval can each step back to the stage before.'),
  ('riskchange', 'intermediate', 'final', null, 3, 'Which stage row is the only one that offers "Implementation", and what else does that row offer?', '["The \"Approval\" row, which also offers a rejection, a cancellation and a step back to \"Review\".", "The \"Review\" row, which also offers \"Rejected\" and \"Cancelled\".", "The \"Approval\" row, which offers nothing else.", "The \"Approval\" row, which also offers \"Closed\" and \"Cancelled\"."]'::jsonb, 0, 'The row reads "Implementation", "Rejected", "Cancelled", "Review". No other row offers the move onto the facility.'),
  ('riskchange', 'intermediate', 'final', null, 4, 'Readable expiry, all levels signed, no rejection, no unfinished action: can a Temporary change leave "Approval" for "Implementation"?', '["It refuses, because a Temporary change must go in on the emergency route.", "It refuses: A temporary change needs an expiry date before it is implemented.", "It allows it, with every condition met.", "It allows it on level 1."]'::jsonb, 2, 'The expiry condition asks for a readable date, and the approval condition asks for every level signed with no rejection. Both are met.'),
  ('riskchange', 'intermediate', 'final', null, 5, 'A set carries three levels and only the first has signed. What does the engine read?', '["Levels 1, 2, 3; outstanding 2, 3; complete yes, since level 1 is the one that decides.", "Two levels outstanding, 2 and 3, so the set is incomplete.", "Levels 1; outstanding none; complete yes.", "Levels 1, 2, 3; outstanding 3."]'::jsonb, 1, 'Every distinct level present must carry at least one Approved row. Levels 2 and 3 have none, so both are outstanding and the set is incomplete.'),
  ('riskchange', 'intermediate', 'final', null, 6, 'Who may decide ES-01''s level 2 approval, as it is assigned?', '["u-emeka or u-halima, since both are independent of ES-01.", "u-emeka, or u-chika when u-emeka is unavailable, since u-chika knows the change.", "Any member signed in who did not raise ES-01.", "u-emeka alone."]'::jsonb, 3, 'The approval is assigned to u-emeka. The engine allows u-emeka to decide it and refuses u-halima, nobody and the originator.'),
  ('riskchange', 'intermediate', 'final', null, 7, 'An Emergency change must go in fast, and its originator is the only person on site. May the originator sign level 1 so the change can go in?', '["No. Under D1 the change originator never decides an approval, on any route.", "Yes. The emergency route suspends the originator rule until the change is ratified.", "Yes, provided an independent approver ratifies level 1 within 7 days.", "No, because an Emergency change needs every level signed before it goes in."]'::jsonb, 0, 'The originator rule is written against the originator by identity, at assignment and at decision. The route needs level 1 signed by somebody allowed to sign it, and nobody having rejected it.'),
  ('riskchange', 'intermediate', 'final', null, 8, 'Level 1 has signed on an Emergency change waiting in "Approval", no approver has objected, and its expiry field is blank. What keeps it out of "Implementation"?', '["Nothing stops it: an Emergency change needs only its first level signed to go in.", "Nothing stops it, because an Emergency change reads its expiry as \"No expiry\".", "The expiry condition: an Emergency change needs a readable expiry.", "The approval condition."]'::jsonb, 2, 'Temporary and Emergency are the two types that must carry an expiry date. The emergency route changes how many levels must sign; it does not lift the expiry condition.'),
  ('riskchange', 'intermediate', 'final', null, 9, 'Which action types can block the gate into the Closed stage?', '["\"Pre-implementation\", \"Implementation\" and \"Post-implementation\", every type left unfinished.", "Implementation and Post-implementation actions left unfinished.", "\"Post-implementation\" alone.", "\"Pre-implementation\" alone."]'::jsonb, 1, 'Pre-implementation actions are the first gate''s business. Into the Closed stage the engine asks that no Implementation or Post-implementation action is unfinished.'),
  ('riskchange', 'intermediate', 'final', null, 10, 'ES-02 is in "Implementation" and AC-03 is still "In progress". Of its two legal next stages, which can it reach today?', '["The Closed stage only, since cancelling a change on the plant needs its work finished first.", "Both, since \"In progress\" work has already been started on the change.", "Neither, until AC-03 reads \"Complete\".", "\"Cancelled\" only."]'::jsonb, 3, 'The Closed stage claims the work is done, so its gate reads AC-03 and refuses. A cancellation withdraws the change, and no action blocks it.'),
  ('riskchange', 'intermediate', 'final', null, 11, 'Tomorrow, 2026-10-02, is the end date of a temporary bypass now running. How many days away is it on 2026-10-01, and which state follows?', '["\"Expiring soon\", 1 day away.", "\"Within expiry\", 1 day.", "\"Expired\", -1.", "\"No expiry\"."]'::jsonb, 0, 'Any expiry from 0 to 14 days away, counted inclusively, reads "Expiring soon". The date has not passed.'),
  ('riskchange', 'intermediate', 'final', null, 12, 'Which expiry state goes with 2026-11-30 on a change already in "Implementation", read on 2026-10-01?', '["\"Expiring soon\", 60 days away, because the expiry lies ahead.", "\"Within expiry\", 14 days away, the most the lead counts.", "\"Within expiry\", 60 days away.", "\"No expiry\"."]'::jsonb, 2, 'Beyond the lead of 14 days a change in effect reads "Within expiry". The count is whole calendar days between the two dates.'),
  ('riskchange', 'intermediate', 'final', null, 13, 'ES-04 is an Emergency change in "Implementation". Which pair of states does it read on 2026-10-01?', '["\"Expiring soon\" and \"Ratification overdue\", due 2026-09-27, since both of its windows are short.", "\"Within expiry\" and \"Ratified\", because it went in on its first signature as the route allows.", "\"No expiry\" and \"Awaiting ratification\".", "\"Within expiry\", and on ratification \"Awaiting ratification\" until 2026-10-03."]'::jsonb, 3, 'ES-04''s expiry is 2026-11-29, beyond the lead. Its ratification due date is after the as-of date, so the window is open. Expiry and ratification are separate questions on one record.'),
  ('riskchange', 'intermediate', 'final', null, 14, 'Implemented on 2026-09-30, an Emergency change still lacks its level 2 signature. When does its window close, and what state holds on 2026-10-01?', '["Due 2026-10-01, \"Awaiting ratification\", counting the window from the as-of date.", "It stays open until 2026-10-07, so the change is \"Awaiting ratification\".", "Due 2026-10-08, \"Awaiting ratification\".", "Due 2026-10-07, \"Ratified\"."]'::jsonb, 1, 'The due date is the actual implementation date plus 7 calendar days. 1 day has gone by, and the window is open.'),
  ('riskchange', 'intermediate', 'final', null, 15, 'Six days after going in on 2026-09-25, an Emergency change with level 2 still unsigned is read on 2026-10-01. What is owed, and by when?', '["Level 2''s signature, by 2026-10-02; meanwhile \"Awaiting ratification\".", "7 days since, due 2026-10-01, \"Ratification overdue\".", "6 days since, due 2026-10-01.", "6 days since, \"Ratified\"."]'::jsonb, 0, '2026-09-25 plus 7 days is 2026-10-02, the day after the as-of date. The window is open.'),
  ('riskchange', 'intermediate', 'final', null, 16, 'ES-05 is an Emergency change in "Implementation", past its target date of 2026-09-20. Which reading is right on 2026-10-01?', '["Overdue yes, and \"Ratification overdue\", since both of its dates have passed.", "Overdue yes, and \"Awaiting ratification\", since the target is the older date.", "Overdue no, and \"Not required\".", "Overdue no, and \"Ratification overdue\"."]'::jsonb, 3, 'A change''s own overdue flag is read only before it is on the facility. "Ratification overdue" is its own state: ES-05''s ratification was due 2026-09-27.'),
  ('riskchange', 'intermediate', 'final', null, 17, 'Which list of stages does a change''s own overdue flag read?', '["Every active stage, \"Implementation\" included, once the target date has passed.", "The in-effect stages, where late work on the facility is measured.", "The active stages that are not in effect.", "The terminal stages, where a change is judged against its date."]'::jsonb, 2, 'A change is overdue only in "Draft", "Screening", "Review" or "Approval", with its target date passed. Late work after that shows as overdue actions.'),
  ('riskchange', 'intermediate', 'final', null, 18, 'Beyond the 5 in "Implementation", what else in the ESANMI register sits on the facility as read on 2026-10-01?', '["None: a change in the Closed stage is finished and off the list.", "ES-06 and ES-07, the 2 in the Closed stage.", "ES-09 and ES-11, the \"Cancelled\" change and the \"Rejected\" one.", "ES-01, which is in \"Approval\" and next in line to go in."]'::jsonb, 1, 'Being on the facility is being in effect, and in effect is "Implementation" and the Closed stage. By stage reads "Closed" 2, which are ES-06 and ES-07. "Cancelled", "Rejected" and "Approval" are not in effect.'),
  ('riskchange', 'intermediate', 'final', null, 19, 'ES-03 went onto the plant with an expiry of 2026-09-28, and its one action AC-08 was cancelled. Give the register''s reading for it on 2026-10-01.', '["\"Expired\", counted in expired, with AC-08 finished and outside openActions.", "\"Expired\", with AC-08 still in openActions.", "\"Expiring soon\", with AC-08 finished.", "\"No expiry\", with AC-08 finished."]'::jsonb, 0, 'ES-03 is in effect and its expiry has passed, so it is the one change in expired 1. A Cancelled action is finished.'),
  ('riskchange', 'intermediate', 'final', null, 20, 'AC-05 is a Post-implementation action on ES-04, "Open", due 2026-10-20. How is it counted on 2026-10-01?', '["In openActions and in overdueActions, because it is open on a change in effect.", "In neither, because ES-04 has not yet been ratified by every level.", "In overdueActions only, because its change is past its target date.", "In openActions only."]'::jsonb, 3, 'ES-04 is live, AC-05 is unfinished, and its due date lies after the as-of date. It is one of the 4 open actions and neither of the 2 overdue ones.'),
  ('riskchange', 'intermediate', 'final', null, 21, 'On ES-09, which was cancelled, AC-07 sits "In progress" with a due date of 2026-08-10. Is it open work or overdue on 2026-10-01?', '["In openActions and overdueActions, because \"In progress\" is unfinished and its date has passed.", "In openActions only, because an action in progress is never overdue.", "In neither count, because ES-09 is \"Cancelled\".", "In neither, because \"In progress\" counts as finished."]'::jsonb, 2, 'Actions on a finished and locked change are not open work. "In progress" is unfinished, but the change behind it is terminal.'),
  ('riskchange', 'intermediate', 'final', null, 22, 'An open action on a live change falls due on 2026-10-02. On 2026-10-01, is it open work, and is it overdue?', '["openActions 0, overdueActions 0, since its date is still ahead of the as-of date.", "Open work that is not yet overdue: openActions 1, overdueActions 0.", "openActions 1, overdueActions 1.", "openActions 0, overdueActions 1."]'::jsonb, 1, 'Whatever its date, unfinished work on a live change counts as open. Overdue needs days until below zero, and 2026-10-02 is 1 day ahead.'),
  ('riskchange', 'intermediate', 'final', null, 23, 'Which of these approval sets reads complete yes?', '["A single signed row that carries no level at all.", "No approval rows at all.", "A lone \"Delegated\" row.", "Levels 1 and 3, with level 3 unsigned."]'::jsonb, 0, 'A row with no level counts as level 1, so one signed row signs the only level. An empty set, a Delegated row and an unsigned level all read complete no.'),
  ('riskchange', 'intermediate', 'final', null, 24, 'One row, marked "Delegated", is all a level has. Is the level signed, and can the row''s assignee still decide it?', '["The level reads signed, and deciding it again is refused: This approval is already approved.", "The level stays outstanding until the delegate decides it, and the delegate may do so.", "The level is dropped from the set, and there is nothing left to decide.", "The level stays outstanding, and deciding it is refused: This approval is already delegated."]'::jsonb, 3, 'Only "Approved" signs a level. A Delegated row counts as decided, so a second decision on it is refused, and the owner''s route for an absence is reassignment.'),
  ('riskchange', 'intermediate', 'final', null, 25, 'A refusal begins "Only the person this approval is assigned to". Which rule produced it?', '["The originator never approves, which is checked at the decision as well.", "A decision is made once, which refuses a second decision on a row.", "Only the assignee decides.", "An approval assigned to nobody."]'::jsonb, 2, 'The assignee refusal answers anybody other than the assignee, nobody signed in included. The originator refusal begins "The originator of a change cannot approve it".'),
  ('riskchange', 'intermediate', 'final', null, 26, 'Work started, work unfinished: a Pre-implementation action reads "In progress" on a fully signed Permanent change with no rejection. Can the change go in?', '["It allows it: the work has begun.", "It refuses, because \"In progress\" is unfinished.", "It refuses, because a Permanent change needs a readable expiry date first.", "It allows it, because Pre-implementation work blocks only the gate into the Closed stage."]'::jsonb, 1, '"In progress" is unfinished, just as "Open" is, and an unfinished Pre-implementation action blocks the gate into "Implementation".'),
  ('riskchange', 'intermediate', 'final', null, 27, 'Besides the engine, what enforces decision D1?', '["The database enforces the same rule.", "Nothing: it is advice to the app.", "The originator.", "The approval level."]'::jsonb, 0, 'The engine holds the rule in its assignment and deciding checks, and the digest records that the database enforces the same rule.'),
  ('riskchange', 'intermediate', 'final', null, 28, 'ES-01''s level 2 approval has been decided "Rejected". Can the same row be decided "Approved" later so the change can go in?', '["Yes, by the assignee, since only the assignee decides the row.", "Yes, once every other level has signed, which outweighs the rejection.", "Yes, by any member independent of the change, which covers the objection.", "No: This approval is already rejected."]'::jsonb, 3, 'A decision is made once, and that is what keeps the rejection rule in place: a rejection anywhere stops the gate with "An approver has rejected this change. It cannot be implemented."'),
  ('riskchange', 'intermediate', 'final', null, 29, 'Day zero of an emergency window: implemented on 2026-10-01 with level 2 outstanding, where does the ratification stand that same day?', '["0 days since, due 2026-10-01, \"Awaiting ratification\", the window ending today.", "0 days since, with due null.", "0 days gone, a window to 2026-10-08, \"Awaiting ratification\".", "0 days since, \"Not required\"."]'::jsonb, 2, 'The window starts on the date the change actually went in, and the due date is 7 days later.'),
  ('riskchange', 'intermediate', 'final', null, 30, 'What do a blank expiry and an expiry reading "after the turnaround" have in common for a Temporary change?', '["The gate refuses both with the same sentence, and in \"Implementation\" both read \"No expiry\".", "The gate allows both, and both read \"Expired\" once in \"Implementation\".", "The gate refuses the blank only.", "Nothing."]'::jsonb, 0, 'Either way the date cannot be read. The gate refuses both, and a change that reached the plant without one reads "No expiry" and can never read "Expired".'),
  ('riskchange', 'intermediate', 'final', null, 31, 'ES-07 went through to the Closed stage; its temporary expiry was 2026-08-01. Which expiry state, and is it in the expired count, on 2026-10-01?', '["\"Expired\", counted, because the expiry is behind the as-of date on a type that carries one.", "\"No expiry\", uncounted, because a closed change is terminal and no longer running.", "\"Expired\", uncounted, because the change is finished and locked in the register.", "\"Closed out\", and outside the expired count."]'::jsonb, 3, 'ES-07 finished on the facility. Its date is long behind 2026-10-01, and the Closed stage turns that into "Closed out" instead of an alarm.'),
  ('riskchange', 'intermediate', 'final', null, 32, 'No implementation date sits on ES-12''s record, and its expiry is 2026-12-31. Read its expiry state, overdue flag and ratification on 2026-10-01.', '["\"Within expiry\", overdue no, \"Awaiting ratification\" with due null.", "\"No expiry\", overdue yes, \"Ratification overdue\".", "\"Within expiry\", overdue no, \"Ratification overdue\" with due null.", "\"Within expiry\", overdue no, \"Not required\"."]'::jsonb, 2, 'With no recorded implementation date the window cannot be shown to be open, so it fails closed. Its expiry is well beyond the lead.'),
  ('riskchange', 'intermediate', 'final', null, 33, 'At which gate is the emergency route''s full review enforced?', '["The gate into \"Implementation\", which waits for every level on every type of change.", "The gate into the Closed stage: it cannot close until every level has signed.", "Neither gate: ratification is only reported.", "The gate into \"Cancelled\"."]'::jsonb, 1, 'The route lets the change in on level 1 and never lets it finish early. The refusal reads: Approval level 2 has not ratified this emergency change. It cannot close until every level has signed.'),
  ('riskchange', 'intermediate', 'final', null, 34, 'What are the values of EXPIRY_LEAD_DAYS and EMERGENCY_RATIFY_DAYS?', '["14 days, counted inclusively, and 7 days from the actual implementation date.", "7 days and 14 days.", "14 days and 8 days.", "15 days and 7 days."]'::jsonb, 0, 'An expiry 14 days away reads "Expiring soon" and 15 days away "Within expiry". A ratification due on the as-of date, day seven, reads "Awaiting ratification".'),
  ('riskchange', 'intermediate', 'final', null, 35, 'Why does ES-08 sit between ES-02 and ES-10 in the urgency order read on 2026-10-01?', '["ES-08''s target date, 2026-09-25, is earlier than every other target in the register.", "ES-08 is the one change in \"Review\", and Review ranks between Implementation and Screening.", "ES-08 carries a lower risk level.", "Overdue ranks after expiring soon and before other live work."]'::jsonb, 3, 'Expired, then expiring soon, then overdue, then other live work, then everything finished. ES-08 is the one overdue change, so it sits between ES-02 and the other live work.'),
  ('riskchange', 'intermediate', 'final', null, 36, 'Four changes are in the register''s total and missing from its active figure on 2026-10-01. Name them.', '["The four changes past their target date, which leave the active count.", "The 4 open actions, which are counted in total and not in active.", "The four finished changes: ES-06, ES-07, ES-09 and ES-11.", "The four Temporary changes."]'::jsonb, 2, 'Active is "Draft", "Screening", "Review", "Approval" and "Implementation". Total counts every row, so the two Closed changes, the Cancelled one and the Rejected one are the difference.'),
  ('riskchange', 'intermediate', 'final', null, 37, 'Which stages offer a rejection as their next move?', '["Every active row, \"Draft\" and \"Implementation\" included, so any live change can be refused.", "From \"Screening\", \"Review\" or \"Approval\" only.", "\"Approval\" alone.", "\"Review\" and \"Approval\"."]'::jsonb, 1, 'A change in "Draft" cannot move to "Rejected", and a change in "Implementation" can only move to "Closed" or "Cancelled".'),
  ('riskchange', 'intermediate', 'final', null, 38, 'A report reads: "ES-02 is expiring soon." What is missing from it?', '["The date it is true on, 2026-10-01, since \"Expiring soon\" moves with the as-of date.", "The type, since \"Expiring soon\" is spelled differently for Emergency changes.", "Nothing: an expiry state holds on every date.", "Its risk level."]'::jsonb, 0, '"Expired", "Expiring soon" and "Within expiry" move with the date. ES-02, expiry 2026-10-14, reads "Expiring soon" on 2026-10-01, and the same record read on another date could read something else.'),
  ('riskchange', 'intermediate', 'final', null, 39, 'A Closed-stage change is picked for another move. Which sentence comes back?', '["A change in Closed can only move to Cancelled, the one exit a finished change keeps.", "It allows \"Cancelled\".", "It refuses: 1 implementation or post-implementation action still open.", "A closed change is final."]'::jsonb, 3, 'Closed, Rejected and Cancelled are the 3 stages that lead nowhere. The refusal lists no moves because there are none to list.'),
  ('riskchange', 'intermediate', 'final', null, 40, 'Only one of these ESANMI readings on 2026-10-01 is a change that fails closed. Which?', '["ES-10, whose past expiry reads \"No expiry\" while the change is still in \"Screening\".", "ES-01, whose ratification reads \"Not required\" with due null.", "ES-12, whose missing implementation date leaves its window unprovable.", "ES-05, due 2026-09-27."]'::jsonb, 2, 'Failing closed is an absence read as a reason to stop or to flag. ES-12''s missing implementation date means its window cannot be shown open. ES-05 is overdue on a real date.'),
  ('riskchange', 'intermediate', 'final', null, 41, 'Name the summary field that tallies changes sitting at the "Approval" stage, with its ESANMI value on 2026-10-01.', '["ratificationPending, which reads 1, since ratification is a later approval.", "awaitingApproval, which reads 1.", "active, which reads 8, the live stages.", "overdue, which reads 1, before the facility."]'::jsonb, 1, 'ES-01 is the one change at that stage, and its two Pending rows do not make it count twice.'),
  ('riskchange', 'intermediate', 'final', null, 42, 'A change with every level signed carries an unfinished "Post-implementation" action. Does that action stop it going into "Implementation"?', '["No. Post-implementation work blocks the gate into the Closed stage, and that is checked later.", "Yes. Any unfinished action blocks both gates.", "Yes, when its due date has passed.", "No, since actions block nothing."]'::jsonb, 0, 'Each gate reads its own action types, so this action waits for the second gate. The first gate asks only about Pre-implementation work.');
